INSERT INTO DimTrade (TradeID, SK_BrokerID, SK_CreateDateID, SK_CreateTimeID, SK_CloseDateID, SK_CloseTimeID, Status, DT_Type, CashFlag, SK_SecurityID, SK_CompanyID, Quantity, BidPrice, SK_CustomerID, SK_AccountID, ExecutedBy, TradePrice, Fee, Commission, Tax, BatchID) WITH TradeEvents AS (SELECT TH.TH_T_ID AS TradeID, MIN(CASE WHEN TH.TH_ST_ID = 'PNDG' OR (TH.TH_ST_ID = 'SBMT' AND T.T_TT_ID IN ('TMB', 'TMS')) THEN TH.TH_DTS END) AS CreateTS, MAX(CASE WHEN TH.TH_ST_ID IN ('CMPT', 'CNCL') THEN TH.TH_DTS END) AS CloseTS, MIN(TH.TH_DTS) AS FirstSeenTS FROM Source.TradeHistory AS TH INNER JOIN Source.Trade AS T ON T.T_ID = TH.TH_T_ID GROUP BY TH.TH_T_ID), DimTradeStaging AS (SELECT T.T_ID AS TradeID, DA.SK_BrokerID AS SK_BrokerID, E.CreateTS AS CreateTS, E.CloseTS AS CloseTS, ST.ST_NAME AS Status, TT.TT_NAME AS DT_Type, CASE WHEN T.T_IS_CASH = '1' THEN TRUE ELSE FALSE END AS CashFlag, DS.SK_SecurityID AS SK_SecurityID, DS.SK_CompanyID AS SK_CompanyID, T.T_QTY AS Quantity, T.T_BID_PRICE AS BidPrice, DA.SK_CustomerID AS SK_CustomerID, DA.SK_AccountID AS SK_AccountID, T.T_EXEC_NAME AS ExecutedBy, T.T_TRADE_PRICE AS TradePrice, T.T_CHRG AS Fee, T.T_COMM AS Commission, T.T_TAX AS Tax, 1 AS BatchID FROM Source.Trade AS T INNER JOIN TradeEvents AS E ON T.T_ID = E.TradeID INNER JOIN Source.StatusType AS ST ON T.T_ST_ID = ST.ST_ID INNER JOIN Source.TradeType AS TT ON T.T_TT_ID = TT.TT_ID LEFT JOIN DimAccount AS DA ON DA.AccountID = T.T_CA_ID AND DA.EffectiveDate <= CAST(E.FirstSeenTS AS DATE) AND CAST(E.FirstSeenTS AS DATE) < DA.EndDate LEFT JOIN DimSecurity AS DS ON DS.Symbol = T.T_S_SYMB AND DS.EffectiveDate <= CAST(E.FirstSeenTS AS DATE) AND CAST(E.FirstSeenTS AS DATE) < DS.EndDate) SELECT TradeID, SK_BrokerID, (SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(CreateTS AS DATE)) AS SK_CreateDateID, (SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(DATE_TRUNC('SECOND', CreateTS) AS TIME)) AS SK_CreateTimeID, (SELECT SK_DateID FROM DimDate WHERE DateValue = CAST(CloseTS AS DATE)) AS SK_CloseDateID, (SELECT SK_TimeID FROM DimTime WHERE TimeValue = CAST(DATE_TRUNC('SECOND', CloseTS) AS TIME)) AS SK_CloseTimeID, Status, DT_Type, CashFlag, SK_SecurityID, SK_CompanyID, Quantity, BidPrice, SK_CustomerID, SK_AccountID, ExecutedBy, TradePrice, Fee, Commission, Tax, BatchID FROM DimTradeStaging